a2a:update-task-status.a2a:status-content:
#[output application/json ---
{
                    taskId: vars.taskId,
                    contextId: vars.contextId,
                    kind: "status-update",
                    status: {
                        state: "input-required",
                        message: {
                            kind: "message", role: "agent", messageId: uuid(),
                            parts: [
                                { kind: "text", text: ("Approval required before the agent can run: " ++ (((vars.pendingTools default []) map ((t) -> ((t.name default "tool") ++ (if ((t.'input'.file_path?)) (" -> " ++ t.'input'.file_path) else "")))) joinBy ", ") ++ ". Reply \"approve\" to allow, or \"deny\" to reject. (Programmatic clients may send a tool-confirmation-response DataPart for per-tool decisions.)") },
                                { kind: "data", data: {
                                    "type": "tool-confirmation-request",
                                    taskId: vars.taskId,
                                    calls: ((vars.pendingTools default []) map ((t) -> { toolUseId: t.toolUseId, name: (t.name default ""), toolType: (t.'type' default "agent.tool_use"), key: (t.key default ""), "input": (t.'input' default {}) }))
                                } }
                            ]
                        }
                    },
                    final: true
                }]

a2a:update-task-artifact.a2a:artifact-content:
#[output application/json ---
{
                    taskId: vars.taskId,
                    contextId: vars.contextId,
                    kind: "artifact-update",
                    artifact: { artifactId: ("answer-" ++ vars.taskId), name: "Answer", parts: [ { kind: "text", text: vars.finalText } ] }
                }]

set-variable.value:
#[output application/java ---
do {
    var approvedPending = ((if (vars.taskRec is Object) (vars.taskRec.pending default []) else [])
        filter ((t) -> (t.'input'.file_path?)
            and ((sizeOf((vars.confirmEvents default []) filter ((d) -> (d.tool_use_id == t.toolUseId) and ((d.result default '') == 'allow')))) > 0))
        map ((t) -> { path: (t.'input'.file_path), content: (t.'input'.content default '') }))
    ---
    (((vars.fileArtifacts default []) ++ approvedPending) groupBy ((f) -> f.path) pluck ((touches, path) -> { path: path, content: (touches[-1].content default '') }))
}]

a2a:update-task-artifact.a2a:artifact-content:
#[output application/json ---
do {
    var base = ((payload.path default "artifact") splitBy "/")[-1] default "artifact"
    ---
    {
        taskId: vars.taskId,
        contextId: vars.contextId,
        kind: "artifact-update",
        artifact: { artifactId: base, name: base, parts: [ { kind: "text", text: (payload.content default "") } ] }
    }
}]

a2a:update-task-status.a2a:status-content:
#[output application/json ---
{
                    taskId: vars.taskId,
                    contextId: vars.contextId,
                    kind: "status-update",
                    status: {
                        state: "completed",
                        message: { kind: "message", role: "agent", messageId: uuid(), parts: [
                            { kind: "data", data: { "type": "run-summary", usage: vars.usage } }
                        ] }
                    },
                    final: true
                }]

#[output application/json ---
do {
    var txt = ((vars.ce.content default []) filter ((b) -> (b.'type' default '') == 'text') map ((b) -> (b.text default '')) joinBy ' ')
    ---
    {
        taskId: vars.taskId,
        contextId: vars.contextId,
        kind: "status-update",
        status: { state: "working", message: { kind: "message", role: "agent", messageId: uuid(), parts: [ { kind: "text", text: ("Tool result: " ++ txt) } ] } },
        final: false
    }
}]

set-variable.value:
#[output application/java ---
do {
    var mu = vars.ce.model_usage default {}
    ---
    {
        input_tokens: ((vars.usage.input_tokens default 0) + (mu.input_tokens default 0)),
        output_tokens: ((vars.usage.output_tokens default 0) + (mu.output_tokens default 0)),
        cache_creation_input_tokens: ((vars.usage.cache_creation_input_tokens default 0) + (mu.cache_creation_input_tokens default 0)),
        cache_read_input_tokens: ((vars.usage.cache_read_input_tokens default 0) + (mu.cache_read_input_tokens default 0)),
        model_requests: ((vars.usage.model_requests default 0) + 1)
    }
}]

#[output application/java ---
((vars.ce.stop_reason.event_ids default []) map ((eid) -> do {
    var tu = (vars.toolUses default {})[eid]
    ---
    { toolUseId: eid, 'type': (tu.'type' default 'agent.tool_use'), name: (tu.name default ''), server: (tu.mcp_server_name default tu.server default '_'), 'input': (tu.'input' default {}) }
}))]

a2a:update-task-status.a2a:status-content:
#[output application/json ---
do {
    var autos = (vars.resolved default []) filter ((r) -> (r.decision default '') != 'defer')
    fun tgt(r) = do {
        var inp = (vars.toolUses default {})[r.toolUseId].'input' default {}
        ---
        if (inp.file_path?) (" -> " ++ inp.file_path)
        else if (inp.command?) (" -> " ++ inp.command)
        else ""
    }
    fun line(r) =
        (if ((r.decision default '') == 'allow') "✓ Auto-approved " else "✕ Auto-denied ")
        ++ "tool " ++ (r.name default 'tool') ++ tgt(r)
        ++ " — by rule '" ++ (r.reasonRule default '?') ++ "' (" ++ (r.reasonSource default 'policy') ++ ")"
    ---
    {
        taskId: vars.taskId,
        contextId: vars.contextId,
        kind: "status-update",
        status: { state: "working", message: { kind: "message", role: "agent", messageId: uuid(), parts: [ { kind: "text", text: ((autos map ((r) -> line(r))) joinBy "\n") } ] } },
        final: false
    }
}]
